  else el.classList.remove('on');
}
const b = document.querySelector('button');
mark(b, true);
console.log(b.className);

topics.intro:
**Суть.** Методи: `el.getAttribute('name')` (значення або `null`), `el.setAttribute('name', 'value')`, `el.removeAttribute('name')`, `el.hasAttribute('name')`. Для `data-*` атрибутів є зручний `el.dataset`: `<a data-user-id="5">` → `a.dataset.userId` (camelCase, значення завжди рядок).

**Приклад на тему (інші значення, ніж у завданнях):**
```js
const a = document.querySelector('a');
console.log(a.getAttribute('href'));
a.setAttribute('target', '_self');
console.log(a.hasAttribute('rel'));    // false
a.removeAttribute('target');
console.log(a.dataset.userId);          // з data-user-id
```

