function clear(el) {
  while (el.firstElementChild) {
    el.firstElementChild.remove();
  }
}
const u = document.querySelector('ul');
clear(u);
console.log(u.children.length);   // 0

topics.intro:
**Суть.** Подія — те, що сталося: клік, ввід, натискання клавіші. `el.addEventListener('click', function)` каже: «коли на цьому елементі станеться click, виклич функцію». Функцію передаємо **без дужок** (це колбек). Одному елементу можна повісити багато слухачів.

**Приклад на тему (інші значення, ніж у завданнях):**
```js
const btn = document.querySelector('button');
btn.addEventListener('click', () => {
  console.log('Клік!');
});
// з винесеною функцією:
function onClick() { console.log('ще клік'); }
btn.addEventListener('click', onClick);
```

